using NUnit.Framework;

namespace Depths.Tests
{
    /// <summary>
    /// The blink against the running game: rows recorded by tools/blink-parity.js on 2026-10-06. Seed
    /// 4242, one inert body in the room (so the charge refills at the in-fight rate), the player at the
    /// centre holding a direction: 20 ticks of the player phase, the blink, then 800 more. Each row:
    /// tick, x, y, vx, vy, lagX, lagY, iframes, blinkGrace, boost, blinkCharges, blinkRegen.
    /// </summary>
    [TestFixture]
    public sealed class BlinkParityTests
    {
        static void Check(int dx, int dy, double aimX, double aimY, double[][] rows)
        {
            var run = new RunState(new Rng(4242)) { dungeon = Dungeon.FromSeed(new Rng(4242)) };
            run.state = "playing";
            run.readyT = 0; run.fadeT = 0;
            var p = run.player;
            p.x = p.lagX = Balance.MidX; p.y = p.lagY = Balance.MidY;
            p.hp = p.maxHp = 8;
            var e = Enemy.Of(BodyKind.Lunger, Balance.RoomLeft + 40, Balance.RoomTop + 40);
            e.noticeTimer = 1000000000;
            run.enemies.Add(e);
            var input = new Input(dx, dy, aimX: aimX, aimY: aimY);
            for (int t = 0; t < 20; t++) TickOrder.TickPlayer(run, input);
            Assert.That(TickOrder.TryBlink(run, input), Is.True);
            int row = 0;
            for (int t = 0; t <= 800; t++)
            {
                if (t > 0) TickOrder.TickPlayer(run, input);
                if (!(t <= 40 || t % 20 == 0)) continue;
                var w = rows[row++];
                string at = " at tick " + t;
                Assert.That(t, Is.EqualTo((int)w[0]));
                Assert.That(p.x, Is.EqualTo(w[1]).Within(1e-6), "x" + at);
                Assert.That(p.y, Is.EqualTo(w[2]).Within(1e-6), "y" + at);
                Assert.That(p.vx, Is.EqualTo(w[3]).Within(1e-6), "vx" + at);
                Assert.That(p.vy, Is.EqualTo(w[4]).Within(1e-6), "vy" + at);
                Assert.That(p.lagX, Is.EqualTo(w[5]).Within(1e-6), "lagX" + at);
                Assert.That(p.lagY, Is.EqualTo(w[6]).Within(1e-6), "lagY" + at);
                Assert.That(p.iframes, Is.EqualTo((int)w[7]), "iframes" + at);
                Assert.That(run.blinkGrace, Is.EqualTo((int)w[8]), "blinkGrace" + at);
                Assert.That(p.boost, Is.EqualTo((int)w[9]), "boost" + at);
                Assert.That(run.blinkCharges, Is.EqualTo((int)w[10]), "charges" + at);
                Assert.That(p.blinkRegen, Is.EqualTo(w[11]).Within(1e-9), "regen" + at);
            }
        }

